using System;
using System.Collections.Generic;
using UnityEngine;

namespace Game.Cube
{
    /// <summary>
    /// The modules the layout draws from. Town modules are fixed and indexed by cell (row-major,
    /// y * N + x), except the centre, which is the Town face's town (TownSquare, 4.5); each science theme lists a pool that
    /// ends with its town module (and Math's island module after it). Generated by Cube > Build Module Library.
    /// </summary>
    public class ModuleLibrary : ScriptableObject, IModuleCatalog, IGateSlotCatalog, IHiddenSlotCatalog
    {
        [Serializable]
        public class ThemePool
        {
            public Theme Theme;
            public List<ScreenModule> Modules = new List<ScreenModule>();
        }

        [SerializeField] private List<ScreenModule> townModules = new List<ScreenModule>();
        [SerializeField] private List<ThemePool> sciencePools = new List<ThemePool>();

        [Tooltip("The Town face's own town module (4.5): the start screen, Town's town (science faces' town modules end their pools).")]
        [SerializeField] private ScreenModule townSquare;

        public IReadOnlyList<ScreenModule> TownModules => townModules;
        public IReadOnlyList<ThemePool> SciencePools => sciencePools;

        /// <summary>The Town face's town module (its centre, the start screen); null in a library built before 4.5.</summary>
        public ScreenModule TownSquareModule => townSquare;

        public void Set(List<ScreenModule> town, List<ThemePool> pools, ScreenModule townSquareModule = null)
        {
            townModules = town;
            sciencePools = pools;
            townSquare = townSquareModule;
        }

        /// <summary>
        /// The fixed Town module for a cell (row-major, y * N + x): one distinct module per cell while the library has
        /// enough (9 at N = 3). Only a larger N than the library covers falls back to wrapping the index.
        /// </summary>
        public ScreenModule TownModule(Vector2Int cell, int faceSize)
        {
            // 4.5: the centre (the start screen) is the Town face's town, on a face big enough for one.
            if (townSquare != null && TownSquare.IsTownCell(cell, faceSize)) return townSquare;
            if (townModules.Count == 0) return null;
            int index = cell.y * faceSize + cell.x;
            return index < townModules.Count ? townModules[index] : townModules[index % townModules.Count];
        }

        public IReadOnlyList<ScreenModule> Pool(Theme theme)
        {
            foreach (ThemePool pool in sciencePools)
                if (pool.Theme == theme) return pool.Modules;
            return Array.Empty<ScreenModule>();
        }

        public ScreenModule Module(Theme theme, int index) => Pool(theme)[index];

        // ---- IModuleCatalog (what CubeLayout needs, without touching scenes) ----

        public int PoolSize(Theme theme) => Pool(theme).Count;

        public int CoreSlotCount(Theme theme, int moduleIndex) => Pool(theme)[moduleIndex].CoreEntranceCount;

        /// <summary>The pool index of a theme's island module (the last of Math's pool), or -1 when it has none.</summary>
        public int IslandModuleIndex(Theme theme)
        {
            IReadOnlyList<ScreenModule> pool = Pool(theme);
            for (int i = 0; i < pool.Count; i++)
                if (pool[i] != null && pool[i].IsIslandScreen) return i;
            return -1;
        }

        /// <summary>The pool index of a theme's town module (4.5: it ends the pool, before Math's island module), or -1.</summary>
        public int TownModuleIndex(Theme theme)
        {
            IReadOnlyList<ScreenModule> pool = Pool(theme);
            for (int i = 0; i < pool.Count; i++)
                if (pool[i] != null && pool[i].IsTownScreen) return i;
            return -1;
        }

        // ---- IGateSlotCatalog (what ItemPlacement needs) ----

        public int GateSlotCount(Theme theme, int moduleIndex) => Pool(theme)[moduleIndex].GateSlotCount;

        // ---- IHiddenSlotCatalog (what HiddenCurrencyPlacement needs) ----

        public int HiddenSlotCount(Theme theme, int moduleIndex) => Pool(theme)[moduleIndex].HiddenItems.Length;
    }
}
